```

gfx::Vector2dF BoxTopLeftOffset(LayoutObject* layout_object,
                                V8CSSBoxType::Enum box_type) {
  auto* box_model = DynamicTo<LayoutBoxModelObject>(layout_object);
  if (!box_model) {
    return gfx::Vector2dF();
  }

  auto localQuadsFn = [&](...) {
    ...
  }

  // A LayoutBox's local coordinate system starts at its border box. Avoid
  // collecting and mapping its fragments for the common relativeTo case.
  if (box_type == V8CSSBoxType::Enum::kBorder && IsA<LayoutBox>(box_model)) {
    DCHECK_EQ(gfx::Vector2dF(), localQuadsFn(...));
    return gfx::Vector2dF();
  }

  return localQuadsFn(...);
}
```

